SELECT qryAnodenrecoatingAktAnoden.[Element Nr], qryAnodenrecoatingAktAnoden.Elektrolyseur, qryAnodenrecoatingAktAnoden.Position, qryAnodenrecoatingAktAnoden.[Anoden Nr], IIf(IsNull([qryLetztesAnodenrecoating].[Anzahl von Rücklieferdatum]),0,[qryLetztesAnodenrecoating].[Anzahl von Rücklieferdatum]) AS AnzRecoatings, qryLetztesAnodenrecoating.[Max von Rücklieferdatum], qryAnodenrecoatingDOL.ElementePassiv, qryAnodenrecoatingDOL.ElementeAktiv, qryAnodenrecoatingDOL.ElementeGesamt, qryAnodenrecoatingDOL.PassiveDOL, qryAnodenrecoatingDOL.AktiveDOL, qryAnodenrecoatingDOL.GesamtDOL
FROM (qryAnodenrecoatingAktAnoden INNER JOIN qryAnodenrecoatingDOL ON qryAnodenrecoatingAktAnoden.[Anoden Nr] = qryAnodenrecoatingDOL.[Anoden Nr]) LEFT JOIN qryLetztesAnodenrecoating ON qryAnodenrecoatingDOL.[Anoden Nr] = qryLetztesAnodenrecoating.Anodennummer;
